@Component("coverageDefinition-handler")
@ProcessingGroup("coverageDefinition-processing-group")
public class CoverageDefinitionEventHandler {
	
	// core constructor
	CoverageDefinitionEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateCoverageDefinitionEvent
     */
    @EventHandler
    public void handle( CreateCoverageDefinitionEvent event) {
        entityManager.persist(new CoverageDefinition(event.getCoverageDefinitionId(), event.getName(), event.getDefaultLimit(), event.getDefaultDeductible(), event.getAsMandatory(), event.getProduct(), event.getCoverageType()));
    }

    /*
     * @param	event UpdateCoverageDefinitionEvent
     */
    @EventHandler
    public CoverageDefinition handle( UpdateCoverageDefinitionEvent event) {
    	entityManager.merge(new CoverageDefinition(event.getCoverageDefinitionId(), event.getName(), event.getDefaultLimit(), event.getDefaultDeductible(), event.getAsMandatory(), event.getProduct(), event.getCoverageType()));
    }
    
    /*
     * @param	event DeleteCoverageDefinitionEvent
     */
    @EventHandler
    public void on( DeleteCoverageDefinitionEvent event) {
    	CoverageDefinition entity = new CoverageDefinition();
   
    	// ------------------------------------------
    	// apply the CoverageDefinitionId
    	// ------------------------------------------
    	entity.setCoverageDefinitionId( event.getCoverageDefinitionId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final CoverageDefinitionRepository coverageDefinitionEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(CoverageDefinitionEventHandler.class.getName());

}
